function mosaicProcess(data,w,h,opts){
  opts=opts||{};
  var b=opts.block!=null?opts.block:12;
  if(b<1)b=1;
  var bw=Math.max(1,Math.round(b));
  var out=new Uint8ClampedArray(data.length);
  for(var by=0;by<h;by+=bw) for(var bx=0;bx<w;bx+=bw){
    var x1=Math.min(w,bx+bw), y1=Math.min(h,by+bw);
    var sr=0,sg=0,sb=0,sa=0,n=0;
    for(var yy=by;yy<y1;yy++) for(var xx=bx;xx<x1;xx++){
      var i=(yy*w+xx)*4; sr+=data[i];sg+=data[i+1];sb+=data[i+2];sa+=data[i+3];n++;
    }
    var ar=sr/n,ag=sg/n,ab=sb/n,aa=sa/n;
    for(var yy2=by;yy2<y1;yy2++) for(var xx2=bx;xx2<x1;xx2++){
      var j=(yy2*w+xx2)*4; out[j]=ar;out[j+1]=ag;out[j+2]=ab;out[j+3]=aa;
    }
  }
  return out;
}

var EXPORTS={mosaicProcess:mosaicProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.MosaicForgePure = EXPORTS; }
